"""Brute-force solvers and tests comparing 3-Coloring with its reduction."""

from __future__ import annotations

import itertools
import random

import problems
from reduce import reduce


# ----------------------------------------------------------------------
# Brute-force solvers written from the problem definitions.

def solve_three_coloring(instance) -> bool:
    n = instance["n"]
    edges = instance["edges"]
    for coloring in itertools.product(range(3), repeat=n):
        if all(coloring[u] != coloring[v] for u, v in edges):
            return True
    return False


def solve_three_sat(instance) -> bool:
    m = instance["num_vars"]
    clauses = instance["clauses"]
    for bits in itertools.product([False, True], repeat=m):
        ok = True
        for clause in clauses:
            if not any((bits[abs(lit) - 1] if lit > 0 else not bits[abs(lit) - 1])
                       for lit in clause):
                ok = False
                break
        if ok:
            return True
    return False


# ----------------------------------------------------------------------
# Instance generation

def random_graph(n, p, rng):
    edges = []
    for u in range(n):
        for v in range(u + 1, n):
            if rng.random() < p:
                edges.append([u, v])
    return {"n": n, "edges": edges}


def all_graphs(n):
    pairs = [(u, v) for u in range(n) for v in range(u + 1, n)]
    for mask in range(1 << len(pairs)):
        edges = [list(pairs[i]) for i in range(len(pairs)) if mask >> i & 1]
        yield {"n": n, "edges": edges}


def main():
    tests_run = 0
    tests_passed = 0

    def check(instance):
        nonlocal tests_run, tests_passed
        tests_run += 1
        problems.ThreeColoring.validate(instance)
        target = reduce(instance)
        problems.ThreeSat.validate(target)
        expected = solve_three_coloring(instance)
        got = solve_three_sat(target)
        assert expected == got, (
            f"MISMATCH on {instance}: expected {expected}, got {got}, "
            f"reduced={target}"
        )
        tests_passed += 1

    # Exhaustive over all graphs with up to 6 vertices.
    for n in range(0, 7):
        for g in all_graphs(n):
            check(g)

    # Random larger graphs.
    rng = random.Random(12345)
    for _ in range(300):
        n = rng.randint(0, 8)
        p = rng.choice([0.1, 0.3, 0.5, 0.7, 0.9])
        check(random_graph(n, p, rng))

    # Explicit edge cases.
    check({"n": 0, "edges": []})
    check({"n": 3, "edges": [[0, 1], [1, 2], [0, 2]]})          # triangle: yes
    check({"n": 4, "edges": [[0, 1], [1, 2], [2, 3], [3, 0], [0, 2], [1, 3]]})  # K4: no
    check({"n": 5, "edges": [[0, 1], [1, 2], [2, 3], [3, 4], [4, 0]]})  # C5: no

    print(f"tests_run={tests_run} tests_passed={tests_passed}")
    assert tests_run == tests_passed


if __name__ == "__main__":
    main()
