# Solvers written from the problem definitions.

def solve_three_coloring(instance) -> bool:
    """Brute force over 3^n colourings (small n)."""
    n = instance["n"]
    edges = instance["edges"]
    for coloring in itertools.product(range(3), repeat=n):
        if all(coloring[u] != coloring[v] for u, v in edges):
            return True
    return False


def solve_three_sat(instance) -> bool:
    """DPLL with unit propagation; exact."""
    m = instance["num_vars"]
    clauses = [list(c) for c in instance["clauses"]]

    def dpll(assignment):
        # assignment: dict var -> bool
        while True:
            # Simplify clauses under current assignment.
            new_clauses = []
            unit = None
            for clause in clauses:
                satisfied = False
                rest = []
                for lit in clause:
                    v = abs(lit)
                    if v in assignment:
                        if assignment[v] == (lit > 0):
                            satisfied = True
                            break
                    else:
                        rest.append(lit)
                if satisfied:
                    continue
                if not rest:
                    return False  # empty clause -> conflict
                if len(rest) == 1:
                    unit = rest[0]
                    break
                new_clauses.append(rest)
            if unit is None:
                clauses[:] = new_clauses
                break
            v = abs(unit)
            val = unit > 0
            if v in assignment and assignment[v] != val:
                return False
            assignment[v] = val
            clauses[:] = new_clauses

        if not clauses:
            return True
        # Choose a variable from the first clause.
        v = abs(clauses[0][0])
        for val in (True, False):
            saved = list(clauses)
            assignment[v] = val
            if dpll(assignment):
                return True
            del assignment[v]
            clauses[:] = saved
        return False

    return dpll({})


# ----------------------------------------------------------------------
# Instance generation

def random_graph(n, p, rng):
    edges = []
    for u in range(n):
        for v in range(u + 1, n):
            if rng.random() < p:
